#!/usr/bin/env python3
"""
WebPilot - one-file launcher.

    python run.py              Start WebPilot and open it in your browser.
    python run.py --port 8080  Use a specific port.
    python run.py --no-browser Start the server without opening a browser.
    python run.py --update     Rebuild the React project (needs Node.js) and
                               embed the fresh build into this file.

The whole app (the production build of the React project) is embedded below,
so this file works on its own: copy it to any computer with Python 3.8+ and
run it. Only the Python standard library is used - nothing to install.
"""

import argparse
import base64
import http.server
import json
import os
import shutil
import socket
import socketserver
import subprocess
import sys
import threading
import webbrowser
import zlib
from pathlib import Path

APP_NAME = "WebPilot"
DEFAULT_PORT = 5173

# Explicit types: Windows sometimes maps .js to text/plain, which breaks module scripts.
MIME = {
    ".html": "text/html; charset=utf-8",
    ".js": "text/javascript; charset=utf-8",
    ".mjs": "text/javascript; charset=utf-8",
    ".css": "text/css; charset=utf-8",
    ".json": "application/json; charset=utf-8",
    ".svg": "image/svg+xml",
    ".png": "image/png",
    ".jpg": "image/jpeg",
    ".jpeg": "image/jpeg",
    ".gif": "image/gif",
    ".webp": "image/webp",
    ".ico": "image/x-icon",
    ".woff": "font/woff",
    ".woff2": "font/woff2",
    ".txt": "text/plain; charset=utf-8",
    ".map": "application/json; charset=utf-8",
}

# === EMBEDDED BUILD START ===
ASSETS = {
    "assets/index-bGYsd4y4.css": "",
    "assets/index-Q8Bzhij7.js": "",
    "index.html": "",
}
# === EMBEDDED BUILD END ===


# --------------------------------------------------------------------------- serving

def load_assets():
    files = {}
    for path, blob in ASSETS.items():
        files["/" + path] = zlib.decompress(base64.b64decode(blob))
    return files


def make_handler(files):
    index = files.get("/index.html")

    class Handler(http.server.BaseHTTPRequestHandler):
        server_version = APP_NAME
        sys_version = ""

        def _send(self, body, ctype, head_only=False, cache=False):
            self.send_response(200)
            self.send_header("Content-Type", ctype)
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Cache-Control", "public, max-age=31536000, immutable" if cache else "no-cache")
            self.send_header("X-Content-Type-Options", "nosniff")
            self.end_headers()
            if not head_only:
                self.wfile.write(body)

        def _serve(self, head_only=False):
            path = self.path.split("?", 1)[0].split("#", 1)[0]
            if path in ("", "/"):
                path = "/index.html"
            body = files.get(path)
            if body is not None:
                ext = os.path.splitext(path)[1].lower()
                self._send(body, MIME.get(ext, "application/octet-stream"), head_only, cache=path.startswith("/assets/"))
            elif index is not None and "." not in path.rsplit("/", 1)[-1]:
                self._send(index, MIME[".html"], head_only)  # single-page app fallback
            else:
                self.send_error(404, "Not found")

        def do_GET(self):
            try:
                self._serve()
            except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
                pass

        def do_HEAD(self):
            try:
                self._serve(head_only=True)
            except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
                pass

        def log_message(self, format, *args):  # keep the console clean
            return

    return Handler


class QuietServer(socketserver.ThreadingMixIn, http.server.HTTPServer):
    daemon_threads = True
    allow_reuse_address = False

    def handle_error(self, request, client_address):
        # Browsers often drop connections early; that is not an error worth printing.
        return


def port_free(port):
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
        try:
            s.bind(("127.0.0.1", port))
            return True
        except OSError:
            return False


def pick_port(preferred):
    for port in list(range(preferred, preferred + 20)) + [0]:
        if port == 0 or port_free(port):
            return port
    return 0


def serve(port, open_browser):
    if not ASSETS:
        print("This file has no embedded app yet. Run:  python run.py --update")
        return 1
    files = load_assets()
    port = pick_port(port)
    httpd = QuietServer(("127.0.0.1", port), make_handler(files))
    url = "http://localhost:%d/" % httpd.server_address[1]

    print("")
    print("  %s is running at  %s" % (APP_NAME, url))
    print("  Press Ctrl+C to stop.")
    print("", flush=True)
    if open_browser:
        threading.Timer(0.6, lambda: webbrowser.open(url)).start()
    try:
        httpd.serve_forever(poll_interval=0.5)
    except KeyboardInterrupt:
        print("  Stopped. Bye!")
    finally:
        httpd.server_close()
    return 0


# --------------------------------------------------------------------------- update

def find_project():
    here = Path(__file__).resolve().parent
    for cand in (here, here / "webpilot-ai", here.parent):
        if (cand / "package.json").is_file() and (cand / "src").is_dir():
            return cand
    return None


def update():
    project = find_project()
    if project is None:
        print("Could not find the WebPilot project folder (package.json + src/) next to this file.")
        return 1
    npm = shutil.which("npm") or shutil.which("npm.cmd")
    if not npm:
        print("Node.js / npm is required for --update. Install it from https://nodejs.org")
        return 1

    def run(args):
        print("  > npm " + " ".join(args))
        result = subprocess.run([npm] + args, cwd=str(project))
        if result.returncode != 0:
            raise SystemExit("npm %s failed." % args[0])

    if not (project / "node_modules").is_dir():
        run(["install", "--no-audit", "--no-fund"])
    run(["run", "build"])

    dist = project / "dist"
    assets = {}
    for f in sorted(dist.rglob("*")):
        if f.is_file():
            rel = f.relative_to(dist).as_posix()
            assets[rel] = base64.b64encode(zlib.compress(f.read_bytes(), 9)).decode("ascii")

    block = "ASSETS = {\n" + "".join("    %s: %s,\n" % (json.dumps(k), json.dumps(v)) for k, v in assets.items()) + "}"
    me = Path(__file__).resolve()
    src = me.read_text(encoding="utf-8")
    start, end = "# === EMBEDDED BUILD START ===\n", "\n# === EMBEDDED BUILD END ==="
    i, j = src.index(start) + len(start), src.index(end)
    me.write_text(src[:i] + block + src[j:], encoding="utf-8", newline="\n")
    size = sum(len(v) for v in assets.values()) // 1024
    print("  Embedded %d files (%d KB) into %s" % (len(assets), size, me.name))
    return 0


# --------------------------------------------------------------------------- main

def main():
    if sys.version_info < (3, 8):
        print("Python 3.8 or newer is required.")
        return 1
    parser = argparse.ArgumentParser(description="Run the WebPilot web research assistant.")
    parser.add_argument("--port", type=int, default=DEFAULT_PORT, help="port to use (default %d)" % DEFAULT_PORT)
    parser.add_argument("--no-browser", action="store_true", help="do not open a browser window")
    parser.add_argument("--update", action="store_true", help="rebuild the project and embed it into this file")
    args = parser.parse_args()
    if args.update:
        return update()
    return serve(args.port, not args.no_browser)


if __name__ == "__main__":
    sys.exit(main())
